def cantor_numbering(N: int) -> str:
    def find_level(N):
        level = 0
        while n > 0:
            level += 1
            n -= (1 << (level - 1))
        return level

    def find_index_in_level(N, level):
        return N - (1 << (level - 1))

    def find_fraction(level, index):
        if level % 2 == 0:
            numerator = 1 + index
            denominator = level - index
        else:
            numerator = level - index
            denominator = 1 + index
        return numerator, denominator

    level = find_level(N)
    index = find_index_in_level(N, level)
    numerator, denominator = find_fraction(level, index)
    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N == 1:
        return "1/1"

    row = 2
    left_sum = 1
    while left_sum + row < N:
        left_sum += row
        row += 1

    step = N - left_sum
    if row % 2 == 0:
        numerator = step
        denominator = row - step + 1
    else:
        numerator = row - step + 1
        denominator = step

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        return "0/0"

    n = 1
    current_position = 1

    while current_position < N:
        n += 1
        current_position += n

    row = n - (current_position - N)
    col = N - (current_position - n) + row - 1

    if n % 2 == 0:
        return f"{col}/{row}"
    else:
        return f"{row}/{col}"

def max_product(num_str: str, N: int, K: int) -> int:
    max_val = float('-inf')

    # Helper function to calculate product between two parts
    def product(left: str, right: str) -> int:
        return int(left) * int(right)

    # Iterate over all possible positions to insert multiplication signs
    for i in range(1, N):
        for j in range(i+1, N):
            if K == 0:
                return product(num_str[:i], num_str[j:])
            elif K == 1:
                return max(product(num_str[:i], num_str[j:]), 
                           product(num_str[:i], num_str[:j]) * product(num_str[j:], num_str[N-j:]))
            else:
                return max(product(num_str[:i], num_str[j:]), 
                           product(num_str[:i], num_str[:j]) * max_product(num_str[j:], N-j, K-1),
                           product(num_str[:i], product(num_str[j:], num_str[N-j:])),
                           max_product(num_str[:i], N-i, K-1) * product(num_str[i:], num_str[N-i:], K-1))

    return max_val

def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i: int, k: int) -> int:
        if k == 0:
            return int(num_str[i:])
        max_prod = 0
        for j in range(i, N - k):
            left = int(num_str[i:j + 1])
            right = dp(j + 1, k - 1)
            max_prod = max(max_prod, left * right)
        return max_prod

    return dp(0, K)

